            inter: { who: 'Mrs Doris Clarke, 82, lives alone', setting: 'The community nurse is visiting you at home.', background: 'You lay on the floor for an hour before your neighbour found you. You are now afraid to go out. You think a personal alarm is “for old people”.', behave: ['Say you have stopped going to the shops.', 'Say you like your rugs; they were a gift.', 'Refuse the alarm at first: “I’m not that old.”', 'Agree to try it if the nurse explains the reason gently.'] },
